// Offline play and updates. The service worker (generated by
// build/service-worker.ts) keeps a copy of the game so a Home Screen app
// starts without a connection. When a new version is published, the browser
// fetches it in the background; it then waits, and the start screen offers
// "New version: tap to update", so a race is never interrupted.

export type OfflineStatus =
  /** No service worker: not supported, or turned off. */
  | 'off'
  /** Setting up the offline copy for the first time. */
  | 'installing'
  /** The game is available offline, and up to date as far as is known. */
  | 'ready'
  /** A new version is downloaded and waiting to take over. */
  | 'update';

export interface Updates {
  readonly status: OfflineStatus;
  /** Checks for a new version now (on launch, and returning to the app). */
  check(): void;
  /** Switches to the waiting new version and reloads. */
  apply(): void;
}

export function setUpUpdates(enabled: boolean, onChange: (status: OfflineStatus) => void): Updates {
  let status: OfflineStatus = 'off';
  let registration: ServiceWorkerRegistration | undefined;
  const set = (next: OfflineStatus) => {
    if (next === status) return;
    status = next;
    onChange(status);
  };

  const updates: Updates = {
    get status() {
      return status;
    },
    check() {
      registration?.update().catch((error: unknown) => console.debug('update check failed: %s', error));
    },
    apply() {
      const waiting = registration?.waiting;
      if (!waiting) return;
      let reloading = false;
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (reloading) return;
        reloading = true;
        location.reload();
      });
      waiting.postMessage({ type: 'SKIP_WAITING' });
    },
  };

  if (!enabled || !('serviceWorker' in navigator)) return updates;

  // A new version is only an "update" if an older one is already in charge;
  // otherwise it is the first install, which needs nothing from the player.
  const watch = (worker: ServiceWorker) => {
    worker.addEventListener('statechange', () => {
      if (worker.state === 'installed') {
        set(navigator.serviceWorker.controller ? 'update' : 'ready');
      }
    });
  };

  set('installing');
  navigator.serviceWorker
    .register('./sw.js', { scope: './' })
    .then((reg) => {
      registration = reg;
      if (reg.waiting && navigator.serviceWorker.controller) set('update');
      else if (reg.active) set('ready');
      if (reg.installing) watch(reg.installing);
      reg.addEventListener('updatefound', () => {
        if (reg.installing) watch(reg.installing);
      });
    })
    .catch((error: unknown) => {
      console.debug('offline play unavailable: %s', error);
      set('off');
    });

  // Returning to the app is when a player would expect to see a new version.
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') updates.check();
  });
  return updates;
}
